    let (out, telemetry) = handle_server_message(resp, &mut p, &mut pc);
    assert!(out["result"]["costGateWarning"].as_str().unwrap().contains("normalized"));
    assert_eq!(telemetry.unwrap().decision, "allow-normalized");
}

